@PostMapping("/payments")
public Payment charge(@RequestHeader("Idempotency-Key") String key,
                       @RequestBody ChargeRequest req) {
    Optional<Payment> existing = paymentRepo.findByIdempotencyKey(key);
    if (existing.isPresent()) {
        return existing.get(); // already processed, return the same result
    }
    Payment payment = paymentGateway.charge(req);
    paymentRepo.save(payment.withIdempotencyKey(key));
    return payment;
}

