// Stateless: the token itself carries everything needed to verify the request
public class AuthFilter {
    boolean isValid(String token) {
        Claims claims = Jwts.parserBuilder()
            .setSigningKey(secretKey)
            .build()
            .parseClaimsJws(token)
            .getBody();
        // No lookup against server-side session storage at all;
        // the signature alone proves the claims have not been tampered with.
        return claims.getExpiration().after(new Date());
    }
}

